import Foundation

/// Product identity generated from the repository-wide `brand.json`.
/// Every product-name, slug, domain, bundle-identifier and URL-scheme
/// reference in the iOS application resolves through this enumeration.
public enum Brand: Sendable {
    public static let name = "Poravia"
    public static let slug = "poravia"
    public static let domain = "poravia.peterdsp.dev"
    public static let websiteURLString = "https://poravia.peterdsp.dev"
    public static let supportEmail = "info@peterdsp.dev"
    public static let bundleIdentifier = "dev.peterdsp.poravia"
    public static let urlScheme = "poravia"
    public static let contractVersion = "1.0.0"
    public static let marketingVersion = "1.0.0"
    public static let repository = "https://github.com/peterdsp/Poravia"
    public static let languageTags: [String] = ["el", "en", "sq"]
    public static let defaultLanguageTag = "el"

    public static var websiteURL: URL {
        guard let url = URL(string: websiteURLString) else {
            preconditionFailure("brand.json carries an invalid url value")
        }
        return url
    }

    public static var supportMailURL: URL {
        guard let url = URL(string: "mailto:\(supportEmail)") else {
            preconditionFailure("brand.json carries an invalid supportEmail value")
        }
        return url
    }

    /// The universal-link prefix the application accepts.
    public static var universalLinkPrefix: String { "https://\(domain)" }

    /// The associated-domain entitlement value for the controlled domain.
    public static var associatedDomainEntitlement: String { "applinks:\(domain)" }

    public static func tagline(forLanguageTag tag: String) -> String {
        switch tag {
        case "el": return "Ταξίδεψε με βεβαιότητα."
        case "en": return "Travel with certainty."
        case "sq": return "Udhëto me siguri."
        default: return taglineDefault
        }
    }

    public static let taglineDefault = "Ταξίδεψε με βεβαιότητα."
}
